function getMailerTransporter() {
  const user = process.env.GMAIL_USER?.trim();
  const pass = process.env.GMAIL_APP_PASSWORD?.trim();
  if (!user || !pass) {
    return null;
  }
  return nodemailer.createTransport({
    service: "gmail",
    auth: {
      user,
      pass
    },
    connectionTimeout: 1e4,
    // 10s connection timeout
    greetingTimeout: 8e3,
    // 8s greeting timeout
    socketTimeout: 15e3
    // 15s socket timeout
  });
}
