      const normalizedChannel = rawChannel === "mobileNumber" || rawChannel === "phone" ? "phone" : rawChannel === "email" ? "email" : "email";
      const cleanTarget = String(newValue || targetValue || "").trim();
      const cleanOtp = String(otp || otpCode || "").trim();
