function recordAudit(req, action, entityType, entityId, details) {
  const adminProfile = req.admin || req.user || {};
  const entry = {
    id: `audit_${Date.now()}_${crypto3.randomInt(100, 999)}`,
    timestamp: (/* @__PURE__ */ new Date()).toISOString(),
    adminId: adminProfile._id || req.adminId || "admin_system",
    adminEmail: adminProfile.email || req.adminEmail || "admin@alikend.com",
    adminRole: adminProfile.role || req.adminRole || "admin",
    action,
    entityType,
    entityId,
    details,
    ipAddress: req.headers["x-forwarded-for"] || req.socket.remoteAddress || "127.0.0.1"
  };
  centralAuditLogs.unshift(entry);
  if (centralAuditLogs.length > 500) {
    centralAuditLogs.pop();
  }
}
