var pendingOtps = {};
function maskIdentity(type, number) {
  const clean = number.replace(/[\s-]/g, "");
  if (type === "aadhaar") {
    const last42 = clean.slice(-4);
    return `XXXX-XXXX-${last42 || "0000"}`;
  }
  if (type === "pan") {
    const last42 = clean.slice(-4);
    return `XXXXX${last42 || "0000"}`;
  }
  const last4 = clean.slice(-4);
  return `ID-\u2022\u2022\u2022\u2022-${last4 || "0000"}`;
}
function maskBankAccount(accountNumber) {
  const clean = accountNumber.replace(/[\s-]/g, "");
  const last4 = clean.slice(-4);
  return `\u2022\u2022\u2022\u2022\u2022\u2022\u2022\u2022${last4 || "0000"}`;
}
async function requirePartnerAuth(req, res, next) {
  const secret = getJwtSecret();
  if (!secret) {
    return res.status(503).json({
      success: false,
      error: "Authentication service unavailable. Please try again."
    });
  }
  const header = req.headers.authorization;
  if (!header || !header.startsWith("Bearer ")) {
    return res.status(401).json({
      success: false,
      error: "Delivery partner authentication required. Please sign in."
    });
  }
  const token = header.slice(7);
  let payload;
  try {
    payload = jwt7.verify(token, secret);
  } catch (err) {
    return res.status(401).json({
      success: false,
      error: "Session expired or invalid. Please log in again."
    });
  }
  if (!payload || payload.role !== "delivery_partner" || !payload.partnerId) {
    return res.status(403).json({
      success: false,
      error: "Access denied. Delivery partner credentials required."
    });
  }
  if (isMongoConnected()) {
    try {
      const partnerDoc = await DeliveryPartner_default.findOne({ partnerId: payload.partnerId });
      if (partnerDoc) {
        req.partnerId = partnerDoc.partnerId;
        req.partner = partnerDoc;
        return next();
      }
    } catch (e) {
      console.warn("MongoDB partner lookup error, falling back:", e);
    }
  }
  const memPartner = memoryStore.deliveryPartners.find(
    (p) => p.partnerId === payload.partnerId
  );
  if (memPartner) {
    req.partnerId = memPartner.partnerId;
    req.partner = memPartner;
    return next();
  }
  return res.status(404).json({
    success: false,
    error: "Delivery partner profile not found."
  });
}
